# /etc/nginx/nginx.conf — blok utama
user  www-data;
worker_processes  auto;   # 1 worker per CPU core (4 core = 4 worker)
worker_cpu_affinity auto; # pin tiap worker ke satu core (kurangi context switch)
pid        /run/nginx.pid;
error_log  /var/log/nginx/error.log warn;

# /etc/nginx/nginx.conf — blok http
http {
    keepalive_timeout  65s;    # tutup koneksi idle setelah 65 detik
    keepalive_requests 1000;   # maks 1000 request per koneksi
    reset_timedout_connection on;  # bebaskan socket dari klien yang sudah pergi

    # Ke upstream (reverse proxy): pakai ulang koneksi ke backend
    upstream app_backend {
        server 127.0.0.1:3000;
        keepalive 32;  # 32 koneksi idle per worker ke backend
    }
}

# /etc/nginx/nginx.conf
events {
    worker_connections 4096;
    use epoll;          # Linux: epoll jauh lebih cepat dari select()
    multi_accept on;    # terima semua koneksi antrean sekaligus
}

http {
    sendfile       on;  # zero-copy untuk file statis
    tcp_nopush     on;  # kirim header + isi dalam satu paket
    tcp_nodelay    on;  # jangan tunda paket kecil (penting untuk API)
    server_tokens  off; # sembunyikan versi NGINX dari header
}

# Benchmark: 10.000 request, 200 koneksi bersamaan
ab -n 10000 -c 200 -k https://api.contoh.id/health

# wrk: 4 thread, 400 koneksi, selama 30 detik
wrk -t4 -c400 -d30s --latency https://api.contoh.id/health

# Aktifkan stub_status untuk monitoring live
# /etc/nginx/conf.d/status.conf
server {
    listen 127.0.0.1:8080;
    location /nginx_status {
        stub_status;
        allow 127.0.0.1;
        deny all;
    }
}

